        and message.get("type") == "constructor"
        and isinstance(message.get("id"), list)
        and isinstance(message.get("kwargs"), dict)
    )


def _message_from_constructor_envelope(message: dict) -> BaseMessage:
    """Reconstruct a message from a Serializable constructor envelope.

    Args:
        message: a dict in the constructor-envelope format, as validated by
            `_is_message_constructor_envelope`.

    Returns:
        The reconstructed message instance.

    Raises:
        ValueError: if the envelope references an unknown or unsupported
            message class.
    """
    class_name = message["id"][-1]
    kwargs = dict(message["kwargs"])

    # Chunk variants (e.g., "HumanMessageChunk") map to their parent type.
    if class_name.endswith("Chunk"):
        class_name = class_name[: -len("Chunk")]

    if class_name == "HumanMessage":
        return HumanMessage(**kwargs)
    if class_name == "AIMessage":
        return AIMessage(**kwargs)
    if class_name == "SystemMessage":
        return SystemMessage(**kwargs)
    if class_name == "ChatMessage":
        return ChatMessage(**kwargs)
    if class_name == "FunctionMessage":
        return FunctionMessage(**kwargs)
    if class_name == "ToolMessage":
        additional_kwargs = kwargs.get("additional_kwargs") or {}
        artifact = kwargs.pop("artifact", None)
        if "artifact" in additional_kwargs:
            artifact = additional_kwargs["artifact"]
        tool_message = ToolMessage(**kwargs)
        if artifact is not None:
            tool_message.artifact = artifact
        return tool_message

    msg = f"Unable to reconstruct message from unsupported class '{class_name}'."
    msg = create_message(message=msg, error_code=ErrorCode.MESSAGE_COERCION_FAILURE)
    raise ValueError(msg)


